        require(address(this).balance >= L);
        c.AdjustBetAmounts(L); if (__ESBMC_reverted()) return;
        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        uint256 before = c.ethBalance(); if (__ESBMC_reverted()) return;
        c.wager{value: L}(); if (__ESBMC_reverted()) return;
        bool recorded = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
