pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 L) internal {
        L = bound(L, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(L > 0);
        vm.assume(address(this).balance >= L);
        try c.AdjustBetAmounts(L) {} catch { return; }
        try c.OpenToThePublic() {} catch { return; }
        uint256 before;
        try c.ethBalance() returns (uint256 __r) { before = __r; } catch { return; }
        try c.wager{value: L}() {} catch { return; }
        bool recorded;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { recorded = __r; } catch { return; }
        uint256 afterBal;
        try c.ethBalance() returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(recorded && afterBal == before + L);
    }

    function testFuzz_run(uint256 L) public {
        _run(L);
    }

    receive() external payable {}
}
